// SignerServiceServer is the server API for SignerService service.
// All implementations must embed UnimplementedSignerServiceServer
// for forward compatibility.
//
// SignerService performs all private-key operations inside the sacred signer
// process. Private key material never crosses this boundary: callers receive
// opaque key handles and public keys only.
//
// The service has no HTTP surface and no database access; it speaks only this
// gRPC contract over UDS/mTLS (AN-4).
type SignerServiceServer interface {
	// GenerateKey creates a new private key inside the signer and returns its
	// handle and public key. The private key never leaves the process.
	GenerateKey(context.Context, *GenerateKeyRequest) (*GenerateKeyResponse, error)
	// GetPublicKey returns the public key for an existing handle.
	GetPublicKey(context.Context, *GetPublicKeyRequest) (*GetPublicKeyResponse, error)
	// Sign produces a signature over a message using the keyed handle.
	Sign(context.Context, *SignRequest) (*SignResponse, error)
	// SignArtifact asks an attached edition-neutral artifact signer to sign a
	// canonical artifact body inside this isolated signer process. Core treats the
	// artifact body as opaque bytes and names only generic routing metadata; the
	// concrete artifact semantics live in the attached edition implementation.
	SignArtifact(context.Context, *SignArtifactRequest) (*SignArtifactResponse, error)
	// VerifyOperation asks an attached edition-neutral operation gate to verify an
	// opaque public operation request inside the signer. Core names only generic
	// routing metadata and opaque evidence/precondition bytes; the attached
	// edition implementation owns the semantics and may return an opaque signed
	// refusal record. No private key material crosses this RPC.
	// These message names predate the Buf naming gate and are part of the
	// control-plane/signer descriptor contract. Renaming either makes the FILE
	// breaking gate fail; suppress only this legacy RPC, not the file or rule.
	// buf:lint:ignore RPC_REQUEST_STANDARD_NAME
	// buf:lint:ignore RPC_RESPONSE_STANDARD_NAME
	VerifyOperation(context.Context, *OperationRequest) (*OperationResponse, error)
	// GatedDestroy asks an attached edition-neutral destruction gate to verify
	// opaque public evidence inside the signer before the signer-local key destroy
	// hook runs. Core names only generic set/evidence/precondition bytes; the
	// attached edition implementation owns the semantics and may return an opaque
	// signed refusal record. The free DestroyKey RPC below remains ungated.
	GatedDestroy(context.Context, *GatedDestroyRequest) (*GatedDestroyResponse, error)
	// A large public evidence segment is streamed in bounded frames. The first
	// frame carries the exact command metadata; the signer hashes and verifies
	// the complete segment before any signer-held key can be destroyed.
	GatedDestroyStream(grpc.ClientStreamingServer[GatedDestroyStreamRequest, GatedDestroyStreamResponse]) error
	// DestroyKey zeroizes and forgets a key handle. It is idempotent.
	DestroyKey(context.Context, *DestroyKeyRequest) (*DestroyKeyResponse, error)
	// ManageKey performs a remote-custody lifecycle command in this isolated
	// signer process. The control plane sends only tenant-scoped public metadata
	// and an outbox-derived operation id; provider credentials and the private
	// key remain signer-side. operation_id makes a redelivered outbox command
	// return the original public result instead of repeating a provider action.
	ManageKey(context.Context, *ManageKeyRequest) (*ManageKeyResponse, error)
	// SignManagedKey signs a digest with a tenant-bound provider key. The
	// ownership lookup and provider private-key operation both run inside this
	// isolated signer process; callers provide only public routing metadata.
	SignManagedKey(context.Context, *SignManagedKeyRequest) (*SignManagedKeyResponse, error)
	// Health reports liveness and readiness. It returns no secret material.
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	// MintSuccessor mints a dual-signed PCAS succession record inside the signer
	// (INT-01). No private key crosses the boundary: the predecessor is referenced
	// by an opaque handle held in the signer, the successor key is generated inside
	// the signer, and only the successor public key and the opaque encoded record
	// are returned. A succession minter must be attached (WithSuccessionMinter) or
	// the signer fails closed with UNIMPLEMENTED. This is the wire path by which the
	// control plane requests a succession without ever obtaining private key
	// material (claims 1/12/49): the control plane can request, but cannot forge.
	MintSuccessor(context.Context, *MintSuccessorRequest) (*MintSuccessorResponse, error)
	// ApplyDelegation durably enforces a tenant-bound PCAS scope or floor inside
	// signer custody and returns a signed readback. Operation ID makes retries
	// exact after a lost worker response.
	ApplyDelegation(context.Context, *ApplyDelegationRequest) (*ApplyDelegationResponse, error)
	// GenerateSuccessorKEM creates a KEM private key inside the signer and returns
	// only the encapsulation public key. The KEM private key is not a signing key:
	// it is held in a signer-side KEM custody store and can be used only through the
	// KEM-specific RPCs below.
	GenerateSuccessorKEM(context.Context, *GenerateSuccessorKEMRequest) (*GenerateSuccessorKEMResponse, error)
	// Decapsulate derives a shared secret from a signer-held KEM private key and a
	// ciphertext. The private key never leaves the signer. The returned shared
	// secret is byte-native secret material for immediate re-wrap use and callers
	// must wipe it after use.
	Decapsulate(context.Context, *DecapsulateRequest) (*DecapsulateResponse, error)
	// RewrapKEMDataKey moves one KEM-wrapped data key from the predecessor KEM
	// key to the successor without the data key leaving signer custody.
	RewrapKEMDataKey(context.Context, *RewrapKEMDataKeyRequest) (*RewrapKEMDataKeyResponse, error)
	// VerifyKEMDataKey opens an envelope under a held KEM key and returns only
	// the data key's SHA-256: the independent readback after a re-wrap.
	VerifyKEMDataKey(context.Context, *VerifyKEMDataKeyRequest) (*VerifyKEMDataKeyResponse, error)
	// ZeroizeKey removes a key from signer custody. It applies to KEM custody first
	// and then falls through to signing-key custody, so retirement can destroy either
	// class through one PCAS RPC.
	ZeroizeKey(context.Context, *ZeroizeKeyRequest) (*ZeroizeKeyResponse, error)
	// GatedIssue drives a gated agent-credential issuance INSIDE the signer over the
	// transport (AGID-INT-WIRE core). It mirrors MintSuccessor: the request carries only
	// the opaque issuance preconditions (a self-describing delegation chain / attestation /
	// agent-stack representation as opaque bytes) and non-secret scalars; the isolated
	// signer runs the attached issuance gate (WithIssuanceGate) which verifies the chain +
	// attestation BEFORE any key op (INV-A1), then, on approval, the attached issuance
	// key-op generates the agent key INSIDE the signer and certifies it under the
	// signer-held issuing CA. Only PUBLIC material crosses back: the issued credential's
	// public key + the opaque encoded issuance/refusal record. No private key ever leaves
	// the boundary. An issuance key-op must be attached (WithIssuanceKeyOp) or the signer
	// fails closed with UNIMPLEMENTED. This is the wire path by which the control plane
	// requests a chain-bound issuance without ever obtaining private key material: it can
	// request, but cannot forge.
	GatedIssue(context.Context, *GatedIssueRequest) (*GatedIssueResponse, error)
	// ProvisionAgentRootAnchor stores a tenant-authorized, PUBLIC
	// AGID delegation root inside the signer floor. The signer refuses a changed
	// first-writer binding and returns its exact durable readback. This removes
	// any need to expose the signer's private keystore to the control plane.
	ProvisionAgentRootAnchor(context.Context, *ProvisionAgentRootAnchorRequest) (*ProvisionAgentRootAnchorResponse, error)
	// GetAgentRootAnchor reads the exact signer-held public AGID root. Callers
	// compare it with the tenant registry before reporting provisioned=true.
	GetAgentRootAnchor(context.Context, *GetAgentRootAnchorRequest) (*GetAgentRootAnchorResponse, error)
	// Bind one public reachability-verdict signer in the isolated signer. The
	// control plane retains its sealed private key; changed first writers refuse.
	ProvisionAgentReachabilityKey(context.Context, *ProvisionAgentReachabilityKeyRequest) (*ProvisionAgentReachabilityKeyResponse, error)
	GetAgentReachabilityKey(context.Context, *GetAgentReachabilityKeyRequest) (*GetAgentReachabilityKeyResponse, error)
	// ProvisionAgentAttestor binds one tenant's PUBLIC attestation verifier key
	// in the signer floor (A150), so a chain-bound mint can verify that tenant's
	// attestation evidence without an operator writing the floor by hand. A
	// changed first-writer binding is refused; the response is the exact durable
	// readback.
	ProvisionAgentAttestor(context.Context, *ProvisionAgentAttestorRequest) (*ProvisionAgentAttestorResponse, error)
	// GetAgentAttestor reads the exact signer-held public attestor key.
	GetAgentAttestor(context.Context, *GetAgentAttestorRequest) (*GetAgentAttestorResponse, error)
	// Tenant domain KEK custody (A123). The signer creates a tenant's domain
	// key-encryption key and keeps it wrapped by an operator-provisioned HSM key
	// named by wrapper_id. The control plane persists only the wrapped form and
	// the binding (tenant, domain, generation) it was created for, and asks the
	// signer to wrap and unwrap the tenant's data keys; the domain KEK itself is
	// opened only inside the signer, for one call, and never crosses this
	// boundary. A signer without tenant KEK custody answers UNIMPLEMENTED.
	CreateTenantDomainKEK(context.Context, *CreateTenantDomainKEKRequest) (*CreateTenantDomainKEKResponse, error)
	// OpenTenantDomainKEK proves the wrapped domain KEK opens under its wrapper
	// and binding, and returns nothing else.
	OpenTenantDomainKEK(context.Context, *OpenTenantDomainKEKRequest) (*OpenTenantDomainKEKResponse, error)
	WrapTenantDataKey(context.Context, *WrapTenantDataKeyRequest) (*WrapTenantDataKeyResponse, error)
	// UnwrapTenantDataKey returns the data key, byte-native secret material the
	// caller must wipe after use.
	UnwrapTenantDataKey(context.Context, *UnwrapTenantDataKeyRequest) (*UnwrapTenantDataKeyResponse, error)
	// RevokeKey administratively revokes a key handle (A128). The key stays in
	// custody, so its public half remains readable and a gated destruction can
	// still retire it, but this signer and every signer process sharing its
	// keystore refuse to sign with it from the next request on. The first
	// revocation holds: a repeat or redelivered request reads back the original
	// operation, reason and time.
	RevokeKey(context.Context, *RevokeKeyRequest) (*RevokeKeyResponse, error)
	// PrepareKeyImport returns the one-time import key for an operation (A128):
	// an operator seals an existing private key to its public half on their own
	// machine, so only sealed bytes cross the control plane. A repeat for the
	// same operation returns the same import key until an import uses it. The
	// import key is held sealed at rest like a signing key and is never a
	// signing key.
	PrepareKeyImport(context.Context, *PrepareKeyImportRequest) (*PrepareKeyImportResponse, error)
	// ImportWrappedKey opens a sealed private key with the operation's import
	// key, under a binding of the tenant, the operation and the public key the
	// private key must match; refuses a key that does not match it or is weak;
	// and keeps it under the requested handle with the requested constraints.
	// Only the public key comes back. The plaintext exists inside the signer for
	// the one call, and the import key is destroyed by the import that uses it.
	ImportWrappedKey(context.Context, *ImportWrappedKeyRequest) (*ImportWrappedKeyResponse, error)
	mustEmbedUnimplementedSignerServiceServer()
}

